import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import '../styles/Inicio.css';
import Hero from '../components/Hero';
import ContactoForm from '../components/ContactoForm';
import ClientesCarrusel from '../components/ClientesCarrusel';
import Testimonios from '../components/Testimonios';
import Equipo from '../components/Equipo';

const Inicio = () => {
  const [menuOpen, setMenuOpen] = useState(false);

  // Cerrar menú al hacer clic fuera
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (!e.target.closest(".menu-dropdown-container")) {
        setMenuOpen(false);
      }
    };
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  return (
    <div className="inicio-container">
      {/* Botón desplegable de menú */}
      <div className="menu-dropdown-container">
        <button
          className={`menu-btn ${menuOpen ? "open" : ""}`}
          aria-expanded={menuOpen}
          onClick={() => setMenuOpen(!menuOpen)}
        >
          <span></span>
        </button>
        {menuOpen && (
          <div className="menu-dropdown">
            <Link to="/servicios" onClick={() => setMenuOpen(false)}>Servicios</Link>
            <Link to="/sobre-nosotros" onClick={() => setMenuOpen(false)}>Sobre Nosotros</Link>
            <Link to="/contacto" onClick={() => setMenuOpen(false)}>Contacto</Link>
            <Link to="/ubicacion-redes" onClick={() => setMenuOpen(false)}>Ubicación y Redes</Link>
          </div>
        )}
      </div>

      {/* Secciones */}
      <Hero />
      <ContactoForm />
      <ClientesCarrusel />
      <Testimonios />
      <Equipo />

      {/* Pie de página */}
      <footer className="footer">
        <div>© 2025 PHG Soluciones Contables.</div>
      </footer>
    </div>
  );
};

export default Inicio;
